import{_ as e,c as n,o as r,ae as o}from"./chunks/framework.Bi6zybwU.js";const m=JSON.parse('{"title":"List Element","description":"List Element","frontmatter":{"title":"List Element","description":"List Element"},"headers":[],"relativePath":"guide/drag-drop-elements/list-element.md","filePath":"guide/drag-drop-elements/list-element.md"}'),a={name:"guide/drag-drop-elements/list-element.md"};function i(s,t,l,d,c,h){return r(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="list-element" tabindex="-1">List Element <a class="header-anchor" href="#list-element" aria-label="Permalink to &quot;List Element&quot;">​</a></h1><p>A list element in a table is used to show a list of items in either ordered or unordered form. Ninja Tables offers a free “List” item to add lists and organize the data of your tables. This helps users list the product features or any data that requires listing. Let’s add a list element in table.</p><h2 id="properties-of-list-element" tabindex="-1"><strong>Properties of List Element</strong> <a class="header-anchor" href="#properties-of-list-element" aria-label="Permalink to &quot;**Properties of List Element**&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Scope</strong></th><th><strong>Option Name</strong></th><th><strong>Type</strong></th></tr></thead><tbody><tr><td><strong>General</strong></td><td>Item Spacing Vertically</td><td>Numeric Value</td></tr><tr><td></td><td>Space Between Icon and Text</td><td>Numeric Value</td></tr><tr><td></td><td>Alignment</td><td>Left, Center, and Right</td></tr><tr><td><strong>Text</strong></td><td>Font Color</td><td>Numeric Value</td></tr><tr><td></td><td>Font Size</td><td>Numeric Value</td></tr><tr><td></td><td>Font Style</td><td>Bold, Italic, and Underline</td></tr><tr><td><strong>List</strong></td><td>List Type</td><td>Unordered or Ordered</td></tr><tr><td></td><td>List Icon (Unordered)</td><td>Circle, Square, Disc, and None</td></tr><tr><td></td><td>List Icon (Ordered)</td><td>Upper-Roman, Lower-Roman, Upper-Alpha, Lower-Alpha, and Decimal</td></tr></tbody></table><h3 id="general" tabindex="-1"><strong>General</strong> <a class="header-anchor" href="#general" aria-label="Permalink to &quot;**General**&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/List-element-general-options-1024x443.png" alt="List element general options"></p><ul><li>**Item Spacing Vertically: **Space between lists vertically. By default, it is set to 20.</li><li>**Space Between Icon and Text: **The space between Icon and the List Text. By default, it is set to 0.</li><li>**Alignment: **You can also position the Lists on either the cell&#39;s Left, center, or right side.</li></ul><h3 id="text" tabindex="-1"><strong>Text</strong> <a class="header-anchor" href="#text" aria-label="Permalink to &quot;**Text**&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/list-element-custom-text-1024x486.png" alt="list element custom text"></p><ul><li><strong>Font Color</strong>: You can change the color of the text. By default, it is set to Black.</li><li><strong>Font Size</strong>: You can change the size of the text. By default, it is set to 15.</li><li>**Font Style: **You can change the Font Style orientations. Available options are <strong>Bold</strong>, <em>Italic</em>, and Underline.</li></ul><h3 id="list-unordered-ordered-list" tabindex="-1"><strong>List</strong> (Unordered &amp; Ordered List) <a class="header-anchor" href="#list-unordered-ordered-list" aria-label="Permalink to &quot;**List** (Unordered &amp; Ordered List)&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/ordered-list-element-1024x601.png" alt="ordered list element"></p><ul><li><strong>List Type:</strong> You can pick from 2 list types- Unordered List and Ordered List.</li><li><strong>List Icon</strong> <strong>(Unordered)</strong>: Change the style of the icons of the lists to Circle, Square, Disc, and None.</li><li><strong>List Icon</strong> <strong>(Ordered)</strong>: Upper-Roman, Lower-Roman, Upper-Alpha, Lower-Alpha, and Decimal.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>We hope this documentation has helped you understand the functionality of this Ninja Tables Drag &amp; Drop Table Builder element.  Let us know your thoughts and questions in the comment box.</p>',15)])])}const u=e(a,[["render",i]]);export{m as __pageData,u as default};
